import http from 'node:http';import * as os from 'os';
os.Worker.parent.onmessage=async({data:port})=>{try{const base='http://127.0.0.1:'+port,response=await fetch(base+'/gzip'),decoded=await response.text(),echo=await new Promise((resolve,reject)=>{const req=http.request(base+'/echo',{method:'POST',agent:false},res=>{const chunks=[];res.on('data',c=>chunks.push(c));res.on('error',reject);res.on('end',()=>resolve(Buffer.concat(chunks).toString()));});req.on('error',reject);req.end('worker HTTP');});os.Worker.parent.postMessage({decoded,echo,alias:(await import('http')).default===http});}catch(e){os.Worker.parent.postMessage({error:String(e)});}os.Worker.parent.onmessage=null;};
